git log --oneline | head -3 && cat >> src/expenseReview.test.ts <<'EOF'

import { reviewExpenses, type Policy } from "./expenseReview";

const policy: Policy = {
  categories: {
    meals: { perItemLimitCents: 5000, dailyLimitCents: 8000 },
    hotel: { perItemLimitCents: 25000 },
    taxi: {},
  },
  receiptRequiredAboveCents: 2000,
};
const rates = { EUR: 0.9412, USD: 0.8 };
const HEADER = "date,employee,category,amount,currency,receipt";
const csv = (...rows: string[]) => [HEADER, ...rows].join("\n");

test("a single CHF row with receipt is reviewed with no violations and totalled as approved", () => {
  const report = reviewExpenses(csv("2026-09-01,Anna,meals,12.50,CHF,yes"), policy, rates);
  expect(report).toEqual({
    lines: [{ line: 2, date: "2026-09-01", employee: "Anna", category: "meals", amountChfCents: 1250, violations: [] }],
    rejected: [],
    totals: { Anna: { approvedCents: 1250, flaggedCents: 0 } },
  });
});
EOF
